package httpcontract_test

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

const (
	createOrderPath = "/v1/orders"

	// Unavailable in the supplied fixture. Replace these with the exact frozen
	// contract names before applying the file.
	idempotencyHeader = "{{IDEMPOTENCY_HEADER_NAME}}"
	commandIDField    = "{{COMMAND_ID_JSON_FIELD}}"
)

// Ported from:
//   repository: {{SOURCE_REPOSITORY}}@{{SOURCE_REVISION}}
//   source: {{SOURCE_PATH}}:{{SOURCE_LINE}}
//   test: {{SOURCE_TEST_FUNCTION}}
// Adaptations:
//   - The source HTTP stack is replaced by the repository's native Go handler fixture.
//   - Command identity is deterministic; the fixture must produce command ID "cmd-7".
//   - Response bytes are captured directly to verify exact idempotent replay.
// Assertions preserved:
//   - POST /v1/orders with quantity "0.0100" and omitted stopLoss returns 201.
//   - The response preserves quantity as the exact string "0.0100".
//   - The response contains stopLoss with the JSON value null.
//   - The response contains command ID "cmd-7".
//   - Repeating the same request and idempotency key returns the same status and body bytes.
//   - Reusing the key with quantity "0.0200" returns 409 and IDEMPOTENCY_KEY_REUSED.
func TestCreateOrder_IdempotencyReplayAndConflict(t *testing.T) {
	// Repository-specific fixture API was not supplied. Replace this call with
	// the existing native handler/router factory. Its deterministic ID source
	// must assign "cmd-7" to the first command.
	handler := newOrdersContractHandler(t)

	const (
		key          = "same-key"
		originalBody = `{"quantity":"0.0100"}`
		changedBody  = `{"quantity":"0.0200"}`
	)

	first := performOrderRequest(t, handler, key, originalBody)
	if first.status != http.StatusCreated {
		t.Fatalf("first request status = %d, want %d; body=%s",
			first.status, http.StatusCreated, first.body)
	}

	firstJSON := decodeJSONObject(t, first.body)

	requireJSONStringField(t, firstJSON, "quantity", "0.0100")
	requireJSONNullField(t, firstJSON, "stopLoss")
	requireJSONStringField(t, firstJSON, commandIDField, "cmd-7")

	replay := performOrderRequest(t, handler, key, originalBody)
	if replay.status != first.status {
		t.Fatalf("replay status = %d, want stored status %d",
			replay.status, first.status)
	}
	if !bytes.Equal(replay.body, first.body) {
		t.Fatalf(
			"replay body is not byte-equivalent:\nfirst:  %q\nreplay: %q",
			first.body,
			replay.body,
		)
	}

	conflict := performOrderRequest(t, handler, key, changedBody)
	if conflict.status != http.StatusConflict {
		t.Fatalf("key-reuse status = %d, want %d; body=%s",
			conflict.status, http.StatusConflict, conflict.body)
	}

	conflictJSON := decodeJSONObject(t, conflict.body)
	requireJSONStringField(
		t,
		conflictJSON,
		"code",
		"IDEMPOTENCY_KEY_REUSED",
	)
}

type recordedHTTPResponse struct {
	status int
	body   []byte
}

func performOrderRequest(
	t *testing.T,
	handler http.Handler,
	idempotencyKey string,
	body string,
) recordedHTTPResponse {
	t.Helper()

	request := httptest.NewRequest(
		http.MethodPost,
		createOrderPath,
		bytes.NewBufferString(body),
	)
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set(idempotencyHeader, idempotencyKey)

	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, request)

	response := recorder.Result()
	defer response.Body.Close()

	responseBody, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatalf("read response body: %v", err)
	}

	return recordedHTTPResponse{
		status: response.StatusCode,
		body:   responseBody,
	}
}

func decodeJSONObject(
	t *testing.T,
	body []byte,
) map[string]json.RawMessage {
	t.Helper()

	var object map[string]json.RawMessage
	if err := json.Unmarshal(body, &object); err != nil {
		t.Fatalf("decode response JSON %q: %v", body, err)
	}
	if object == nil {
		t.Fatalf("response JSON = null, want object")
	}

	return object
}

func requireJSONStringField(
	t *testing.T,
	object map[string]json.RawMessage,
	field string,
	want string,
) {
	t.Helper()

	raw, exists := object[field]
	if !exists {
		t.Fatalf("response field %q is absent", field)
	}

	var got string
	if err := json.Unmarshal(raw, &got); err != nil {
		t.Fatalf("response field %q is not a JSON string: %s", field, raw)
	}
	if got != want {
		t.Fatalf("response field %q = %q, want %q", field, got, want)
	}
}

func requireJSONNullField(
	t *testing.T,
	object map[string]json.RawMessage,
	field string,
) {
	t.Helper()

	raw, exists := object[field]
	if !exists {
		t.Fatalf("response field %q is absent; want explicit null", field)
	}
	if !bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		t.Fatalf("response field %q = %s, want null", field, raw)
	}
}
